COMMENT ON COLUMN USER_PROFILES.LANGUAGE_ID IS 'Preferred interface language' 
;

COMMENT ON COLUMN USER_PROFILES.SITUATION_ID IS 'Chosen life situation' 
;

COMMENT ON COLUMN USER_PROFILES.ARRIVAL_DATE IS 'Anchor for deadlines counted from arrival' 
