CREATE TABLE USER_PROGRESS 
    ( 
     USER_ID          NUMBER (10)  NOT NULL , 
     PROCEDURE_ID     NUMBER (10)  NOT NULL , 
     STATUS           VARCHAR2 (20 CHAR) DEFAULT 'TODO'  NOT NULL , 
     DONE_AT          DATE , 
     DONE_WITH_HELPER NUMBER (1) DEFAULT 0  NOT NULL , 
     UPDATED_AT       TIMESTAMP DEFAULT SYSTIMESTAMP  NOT NULL 
    ) 
    LOGGING 
;

COMMENT ON TABLE USER_PROGRESS IS 'Status of each procedure in the client plan'
;

COMMENT ON COLUMN USER_PROGRESS.STATUS IS 'TODO / IN_PROGRESS / DONE / SKIPPED' 
;

COMMENT ON COLUMN USER_PROGRESS.DONE_WITH_HELPER IS 'Marked as done together with a helper' 
;
