    ( 
     PROCEDURE_ID ASC 
    ) 
    LOGGING 
;

ALTER TABLE USER_PROGRESS 
    ADD CONSTRAINT CK_UPG_DONE_WITH_HELPER 
    CHECK (DONE_WITH_HELPER IN (0, 1))
;


ALTER TABLE USER_PROGRESS 
    ADD CONSTRAINT CK_UPG_STATUS 
    CHECK (STATUS IN ('TODO', 'IN_PROGRESS', 'DONE', 'SKIPPED'))
;
ALTER TABLE USER_PROGRESS 
    ADD CONSTRAINT PK_USER_PROGRESS PRIMARY KEY ( USER_ID, PROCEDURE_ID ) ;

CREATE TABLE USERS 
    ( 
     ID            NUMBER (10) GENERATED BY DEFAULT AS IDENTITY 
        ( START WITH 1 )  NOT NULL , 
     EMAIL         VARCHAR2 (254 CHAR)  NOT NULL , 
     PASSWORD_HASH VARCHAR2 (255 CHAR)  NOT NULL , 
     ROLE_ID       NUMBER (10)  NOT NULL , 
     STATUS        VARCHAR2 (20 CHAR) DEFAULT 'ACTIVE'  NOT NULL , 
     FAILED_LOGINS NUMBER (3) DEFAULT 0  NOT NULL , 
     CONSENT_AT    TIMESTAMP  NOT NULL , 
     CREATED_AT    TIMESTAMP DEFAULT SYSTIMESTAMP  NOT NULL , 
     LAST_LOGIN_AT TIMESTAMP 
    ) 
    LOGGING 
;

COMMENT ON TABLE USERS IS 'Accounts (login data only)'
;

COMMENT ON COLUMN USERS.PASSWORD_HASH IS 'Argon2id / bcrypt hash, never the password' 
;

COMMENT ON COLUMN USERS.STATUS IS 'ACTIVE / BLOCKED' 
;

COMMENT ON COLUMN USERS.FAILED_LOGINS IS 'Counter for login throttling' 
;

COMMENT ON COLUMN USERS.CONSENT_AT IS 'GDPR consent given at registration' 
;
CREATE INDEX IDX_USR_ROLE ON USERS 
    ( 
     ROLE_ID ASC 
    ) 
    LOGGING 
;

ALTER TABLE USERS 
    ADD CONSTRAINT CK_USR_STATUS 
    CHECK (STATUS IN ('ACTIVE', 'BLOCKED'))
;
